{"implementation": "def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be a dict")
    if 'threshold' not in case or 'calls' not in case:
        raise ValueError("case must contain 'threshold' and 'calls'")
    threshold = case['threshold']
    calls = case['calls']
    if not isinstance(threshold, (int, float)):
        raise ValueError("threshold must be numeric")
    if not isinstance(calls, list):
        raise ValueError("calls must be a list")
    diagnostics = []
    accepted_ids = []
    for call in calls:
        required = ['call_id','loss_without_call','loss_with_call','prediction_tokens','parseable']
        for field in required:
            if field not in call:
                raise ValueError(f"Missing field {field} in call")
        call_id = call['call_id']
        loss_without = call['loss_without_call']
        loss_with = call['loss_with_call']
        pred_tokens = call['prediction_tokens']
        parseable = call['parseable']
        if pred_tokens <= 0:
            raise ValueError("prediction_tokens must be positive")
        gain = round(loss_without - loss_with, 8)
        normalized_gain = round(gain / pred_tokens, 8)
        diag = {
            'call_id': call_id,
            'gain': gain,
            'normalized_gain': normalized_gain,
            'parseable': parseable,
            'loss_without_call': loss_without,
            'loss_with_call': loss_with,
            'prediction_tokens': pred_tokens
        }
        diagnostics.append(diag)
        if parseable and normalized_gain >= threshold:
            accepted_ids.append(call_id)
    return {
        'accepted_call_ids': accepted_ids,
        'diagnostics': diagnostics
    }"}
